<?php
require_once __DIR__.'/lib/auth.php';requireAuth();require_once __DIR__.'/lib/workspace.php';require_once __DIR__.'/lib/application_match.php';$pdo=db();$candidates=loadCandidateRecords();
$stats=$pdo->query("SELECT COUNT(*) resumes,SUM(stage='Interview') interviews,SUM(stage='Offer') offers FROM candidates")->fetch();$jobTotal=(int)$pdo->query("SELECT COUNT(*) FROM jobs WHERE status IN ('open','draft')")->fetchColumn();$selectedTotal=(int)$pdo->query("SELECT COUNT(*) FROM wishlist_items WHERE disposition='selected'")->fetchColumn();
$jobs=$pdo->query("SELECT j.*,COUNT(DISTINCT c.id) applicants,COUNT(DISTINCT CASE WHEN wi.disposition='wishlist' THEN wi.candidate_id END) shortlisted,COUNT(DISTINCT CASE WHEN wi.disposition='selected' THEN wi.candidate_id END) selected,wp.id profile_id FROM jobs j LEFT JOIN candidates c ON c.job_id=j.id LEFT JOIN wishlist_profiles wp ON wp.job_id=j.id LEFT JOIN wishlist_items wi ON wi.profile_id=wp.id GROUP BY j.id,wp.id ORDER BY applicants DESC,FIELD(j.status,'open','draft','paused','closed'),j.created_at DESC")->fetchAll();
$jobMap=[];foreach($jobs as $job)$jobMap[(int)$job['id']]=$job;$scoreComparisons=[];
foreach($candidates as $candidate){$candidateJob=$jobMap[(int)($candidate['job_id']??0)]??null;if(!$candidateJob)continue;$evidence=applicationEvidenceMatch($candidate,$candidateJob);if(!$evidence['configured']||!$evidence['analyzed'])continue;$scoreComparisons[]=['candidate'=>$candidate,'job'=>$candidateJob,'evidence'=>$evidence];}
usort($scoreComparisons,fn($a,$b)=>$b['evidence']['score']<=>$a['evidence']['score']?:strcmp((string)$a['candidate']['name'],(string)$b['candidate']['name']));$scoreComparisons=array_slice($scoreComparisons,0,10);
$countries=$pdo->query("SELECT country_code,country_name,COUNT(*) total FROM candidates WHERE COALESCE(country_code,country_name,'')<>'' GROUP BY country_code,country_name ORDER BY total DESC")->fetchAll();foreach($countries as &$country)$country['country_code']=countryCodeFromName($country['country_code'],$country['country_name']);unset($country);$sources=$pdo->query('SELECT source_name,COUNT(*) total FROM candidates GROUP BY source_name ORDER BY total DESC')->fetchAll();$stageRows=$pdo->query('SELECT stage,COUNT(*) total FROM candidates GROUP BY stage')->fetchAll();$stageMap=[];foreach($stageRows as $r)$stageMap[$r['stage']]=$r['total'];
$skills=[];$experience=['Under 1 year'=>0,'1–3 years'=>0,'3–5 years'=>0,'5+ years'=>0,'Unavailable'=>0];foreach($candidates as $candidate){foreach(array_unique($candidate['skills']??[]) as $skill)$skills[$skill]=($skills[$skill]??0)+1;$months=(int)($candidate['experience']['total_months']??0);if(!$months)$experience['Unavailable']++;elseif($months<12)$experience['Under 1 year']++;elseif($months<36)$experience['1–3 years']++;elseif($months<60)$experience['3–5 years']++;else$experience['5+ years']++;}arsort($skills);$skills=array_slice($skills,0,12,true);$maxSkill=max($skills?:[1]);$maxExperience=max($experience?:[1]);
$activePage='dashboard';$pageTitle='Dashboard · ResumeIQ';$pageStyles='<style>.hero{padding:21px;display:flex;justify-content:space-between;align-items:center;background:linear-gradient(120deg,#fff 55%,#f0edff)}.hero h1{font-size:25px;margin:4px 0}.hero p{font-size:10px;color:var(--muted)}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-top:9px}.metric{padding:15px;display:flex;gap:11px;align-items:center}.metric i{width:38px;height:38px;display:grid;place-items:center;background:var(--primary-soft);color:var(--primary);border-radius:9px}.metric strong{font-size:21px;display:block}.metric span{font-size:8px;color:var(--muted)}.dash{display:grid;grid-template-columns:minmax(0,1fr) 370px;gap:10px;margin-top:10px}.box{padding:16px}.title{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.title h2{margin:0;font-size:13px}.jobs{display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.job{padding:14px;border:1px solid var(--line);border-radius:9px;background:linear-gradient(145deg,#fff,#fcfbff)}.job:first-child{border-color:#d9d0ff;background:#f8f6ff}.job h3{margin:0 0 5px;font-size:14px}.job p{font-size:9px;color:var(--muted);min-height:28px}.job-meta,.actions{display:flex;gap:6px;flex-wrap:wrap}.job-meta{margin:9px 0}.actions .btn{height:29px;padding:0 8px;font-size:9px}.world{background:#fafafe;border:1px solid var(--line);padding:8px;overflow:hidden}.world-map{width:100%;height:auto;max-height:245px;display:block}.world-map path{fill:#e4e0f7;stroke:#fff;stroke-width:.45;transition:.15s}.world-map path.has-data{cursor:pointer}.map-state{min-height:220px;display:grid;place-items:center;text-align:center;color:var(--muted);font-size:12px}.map-state i{font-size:24px;color:var(--primary);margin-right:8px}.country{display:flex;justify-content:space-between;padding:6px 0;font-size:9px;border-bottom:1px solid var(--line)}.chart-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px}.chart-row{display:grid;grid-template-columns:105px 1fr 55px;gap:7px;align-items:center;padding:6px 0;font-size:9px}.track{height:7px;background:#efeff5;overflow:hidden;border-radius:3px}.track i{display:block;height:100%;background:linear-gradient(90deg,var(--primary),#9277ff)}.experience .track i{background:linear-gradient(90deg,#21b77d,#78d8b5)}.score-compare{margin-top:10px}.compare-note{padding:10px;margin-bottom:10px;border:1px solid #ddd6ff;background:#f8f6ff;color:var(--muted);font-size:9px}.compare-table{width:100%;border-collapse:collapse}.compare-table th,.compare-table td{padding:10px 8px;border-bottom:1px solid var(--line);text-align:left;font-size:9px}.compare-table th{color:var(--muted);text-transform:uppercase;font-size:8px}.compare-table strong,.compare-score{font-size:12px}.compare-score.evidence{color:var(--primary)}.delta-up{color:var(--green)}.delta-down{color:var(--danger)}.mapping-summary{display:flex;gap:5px;flex-wrap:wrap}.mapping-summary span{padding:3px 5px;border-radius:4px;background:#f1eff8}.mapping-summary .confirmed{background:var(--green-soft);color:var(--green)}.mapping-summary .review{background:#fff5e7;color:#8c610d}.mapping-summary .missing{background:#fff0f2;color:var(--danger)}.funnel{display:grid;grid-template-columns:repeat(5,1fr);gap:5px}.funnel div{text-align:center;padding:8px;background:#fafafe}.funnel strong{display:block}@media(max-width:1000px){.dash{grid-template-columns:1fr}.metric-grid,.jobs{grid-template-columns:repeat(2,1fr)}}@media(max-width:620px){.metric-grid,.jobs,.chart-grid{grid-template-columns:1fr}.hero{align-items:flex-start;gap:12px;flex-direction:column}}</style>';require __DIR__.'/views/partials/header.php';?>
<section class="panel hero"><div><div class="kicker">Recruitment command center</div><h1>Hiring overview</h1><p>Actual resume, job, skill, experience and location data in one workspace.</p></div><a class="btn btn-primary" href="job_edit.php"><i class="fa-solid fa-plus"></i>Create job</a></section>
