<section class="dash"><main><article class="panel box" id="jobs"><div class="title"><div><h2>Jobs by applicant volume</h2><small>Highest-volume job appears first.</small></div><a href="pipeline.php">All pipeline</a></div><div class="jobs"><?php foreach($jobs as $job):$description=trim(preg_replace('/\s+/',' ',html_entity_decode(strip_tags($job['description']),ENT_QUOTES|ENT_HTML5,'UTF-8')));?><article class="job"><h3><?=htmlspecialchars(trim($job['title']))?></h3><p><?=htmlspecialchars(mb_strimwidth($description,0,120,'…'))?></p><div class="job-meta"><span class="tag"><b><?=(int)$job['applicants']?></b> applicants</span><span class="tag"><?=(int)$job['shortlisted']?> wishlist</span><span class="tag"><?=(int)$job['selected']?> selected</span><span class="tag"><?=htmlspecialchars($job['status'])?></span></div><div class="actions"><?php if($job['profile_id']):?><a class="btn" href="job_profile.php?id=<?=$job['profile_id']?>">Top 5</a><a class="btn" href="wishlist.php?profile=<?=$job['profile_id']?>">Wishlist</a><?php endif?><a class="btn" href="pipeline.php?job_id=<?=$job['id']?>">Pipeline</a><a class="btn" href="job_edit.php?id=<?=$job['id']?>">Edit</a><?php if($job['public_url']):?><a class="btn" target="_blank" rel="noopener" href="<?=htmlspecialchars($job['public_url'])?>">Public job</a><?php endif?></div></article><?php endforeach?></div></article>
<article class="panel box score-compare"><div class="title"><div><h2>Evidence v1 application ranking</h2><small>Top job-scoped applications by evidence score.</small></div><span class="tag">Advisory · AI off</span></div><div class="compare-note">Evidence v1 weighs required-skill evidence, requirement-level experience, preferred skills, role similarity and evidence strength. Related skills remain review-only and receive limited credit.</div><?php if(!$scoreComparisons):?><div class="empty">Add required skills to jobs and analyze their applicants to compare scores.</div><?php else:?><div style="overflow:auto"><table class="compare-table"><thead><tr><th>Candidate / job</th><th>Evidence v1</th><th>Requirement mapping</th></tr></thead><tbody><?php foreach($scoreComparisons as $comparison):$person=candidatePresentation($comparison['candidate']);$mapping=$comparison['evidence']['mapping'];$confirmed=count(array_filter($mapping,fn($item)=>$item['status']==='experience_backed'));$review=count(array_filter($mapping,fn($item)=>in_array($item['status'],['skills_only','related_review'],true)));$missing=count(array_filter($mapping,fn($item)=>$item['status']==='not_found'));?><tr><td><strong><a href="candidate_detail.php?id=<?=urlencode($comparison['candidate']['id'])?>"><?=htmlspecialchars($person['name'])?></a></strong><br><span class="muted"><?=htmlspecialchars($comparison['job']['title'])?></span></td><td><span class="compare-score evidence"><?=$comparison['evidence']['score']?>%</span><br><span class="muted">Evidence weighted</span></td><td><div class="mapping-summary"><span class="confirmed"><?=$confirmed?> experience-backed</span><span class="review"><?=$review?> review</span><span class="missing"><?=$missing?> not found</span></div></td></tr><?php endforeach?></tbody></table></div><?php endif?></article>
<section class="chart-grid"><article class="panel box"><div class="title"><h2>Top resume skills</h2><a href="analytics.php">Details</a></div><?php foreach($skills as $skill=>$count):?><a class="chart-row" href="candidates.php?skill=<?=urlencode($skill)?>"><span><?=htmlspecialchars($skill)?></span><div class="track"><i style="width:<?=round($count/$maxSkill*100)?>%"></i></div><b><?=$count?> · <?=round($count/max(1,count($candidates))*100)?>%</b></a><?php endforeach?><?php if(!$skills):?><div class="empty">No parsed skill evidence yet.</div><?php endif?></article><article class="panel box experience"><div class="title"><h2>Experience distribution</h2><span class="tag"><?=count($candidates)?> candidates</span></div><?php foreach($experience as $label=>$count):?><div class="chart-row"><span><?=$label?></span><div class="track"><i style="width:<?=round($count/$maxExperience*100)?>%"></i></div><b><?=$count?> · <?=round($count/max(1,count($candidates))*100)?>%</b></div><?php endforeach?></article></section>
<article class="panel box" style="margin-top:10px"><div class="title"><h2>Hiring funnel</h2><a href="pipeline.php">Open board</a></div><div class="funnel"><?php foreach(['Applied','Screening','Interview','Offer','Rejected'] as $stage):?><div><strong><?=$stageMap[$stage]??0?></strong><small><?=$stage?></small></div><?php endforeach?></div></article></main>
<aside><article class="panel box"><div class="title"><h2>Candidate locations</h2><span class="tag"><?=count($countries)?> countries</span></div><div class="world" id="world"><div class="map-state" id="mapState"><i class="fa-solid fa-earth-asia"></i> Loading candidate map…</div></div><?php foreach($countries as $country):?><a class="country" href="candidates.php?country=<?=urlencode($country['country_code'])?>"><span><?=htmlspecialchars($country['country_name']?:$country['country_code'])?></span><b><?=$country['total']?> · <?=round($country['total']/max(1,$stats['resumes'])*100)?>%</b></a><?php endforeach?></article><article class="panel box" style="margin-top:10px"><div class="title"><h2>Resume sources</h2><a href="sources.php">Manage</a></div><?php foreach($sources as $source):?><div class="country"><span><?=htmlspecialchars($source['source_name'])?></span><b><?=$source['total']?></b></div><?php endforeach?></article></aside></section>
<script>const data=<?=json_encode(array_column($countries,null,'country_code'),JSON_HEX_TAG|JSON_HEX_AMP)?>,total=<?=max(1,(int)$stats['resumes'])?>;fetch('assets/world.svg').then(r=>r.text()).then(t=>{const svg=new DOMParser().parseFromString(t,'image/svg+xml').documentElement;svg.removeAttribute('width');svg.removeAttribute('height');svg.setAttribute('viewBox','0 0 1009.6727 665.96301');svg.setAttribute('preserveAspectRatio','xMidYMid meet');svg.classList.add('world-map');Object.entries(data).forEach(([code,c])=>{if(!code)return;const p=svg.querySelector('#'+CSS.escape(code));if(!p)return;const strength=.35+.65*(c.total/Math.max(...Object.values(data).map(x=>x.total)));p.classList.add('has-data');p.style.fill='rgba(111,69,255,'+strength+')';const title=document.createElementNS('http://www.w3.org/2000/svg','title');title.textContent=(c.country_name||code)+': '+c.total+' resumes ('+Math.round(c.total/total*100)+'%)';p.appendChild(title);p.dataset.country=code});document.getElementById('world').replaceChildren(svg);document.querySelectorAll('.world-map path.has-data').forEach(p=>p.onclick=()=>location.href='candidates.php?country='+encodeURIComponent(p.dataset.country))}).catch(()=>{document.getElementById('mapState').textContent='Candidate map could not be loaded. Refresh to try again.'});</script><?php require __DIR__.'/views/partials/footer.php';?>
